<?php require_once '../includes/auth.php';require_admin();verify_csrf();$title=trim($_POST['title']??'');$msg=trim($_POST['message']??'');$priority=$_POST['priority']??'normal';$target=$_POST['target_type']??'all';$code=strtoupper(trim($_POST['target_institution_code']??''));$due=$_POST['due_date']??null;if($title===''||$msg===''||!in_array($priority,['normal','high','urgent'],true)||!in_array($target,['all','ashram_shala','wastigruh'],true))exit('Invalid order');$s=mysqli_prepare($conn,"INSERT INTO officer_orders(title,message,priority,target_type,target_institution_code,due_date,created_by) VALUES(?,?,?,?,?,?,?)");$uid=user()['id'];mysqli_stmt_bind_param($s,'ssssssi',$title,$msg,$priority,$target,$code,$due,$uid);mysqli_stmt_execute($s);$id=mysqli_insert_id($conn);$safeT=mysqli_real_escape_string($conn,$target);$safeC=mysqli_real_escape_string($conn,$code);mysqli_query($conn,"INSERT INTO alerts(type,title,message,severity,institution_type,institution_code) VALUES('system','".mysqli_real_escape_string($conn,$title)."','".mysqli_real_escape_string($conn,$msg)."','".($priority==='urgent'?'urgent':($priority==='high'?'warning':'info'))."','".$safeT."','".$safeC."')");log_activity('created','orders',$title,$id);flash('success','Official order published.');redirect('orders.php');
